final class BowVerification {
    private static final BlockPos POS=new BlockPos(1808,150,0);
    private static void clearArrows(ServerLevel l){l.getEntitiesOfClass(AbstractArrow.class,new AABB(POS).inflate(64)).forEach(Entity::discard);}
    private static List<PrimalArrow> shots(ServerLevel l){return l.getEntitiesOfClass(PrimalArrow.class,new AABB(POS).inflate(64));}
    private static net.minecraft.world.entity.animal.Pig target(ServerLevel l,int i){var pig=EntityType.PIG.create(l);pig.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(80);pig.setHealth(80);pig.setPos(POS.getX()+i*2,POS.getY()+10,POS.getZ()+30);return pig;}
    static void run(ServerLevel l,BiConsumer<Boolean,String> check){
        for(int x=-4;x<=48;x++)for(int z=-4;z<=48;z++){var p=POS.offset(x,0,z);l.getChunkAt(p);for(int y=-2;y<=18;y++)l.setBlock(p.above(y),Blocks.AIR.defaultBlockState(),18);}clearArrows(l);
        var p=new FakePlayer(l,new GameProfile(UUID.fromString("15733050-0df2-4482-acf1-65e8ac4a4203"),"TC4_Bow_Test")){void drawTicks(int ticks){useItemRemaining=getUseItem().getUseDuration(this)-ticks;}};
        p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.moveTo(POS.getCenter());p.setYRot(-90);p.setXRot(0);p.getInventory().clearContent();var bow=new ItemStack(Items.BOW);p.setItemInHand(InteractionHand.MAIN_HAND,bow);p.getInventory().setItem(2,new ItemStack(Items.ARROW,64));p.getInventory().setItem(4,new ItemStack(R3Equipment.PRIMAL_ARROWS.get(0).get(),3));p.getInventory().setItem(5,new ItemStack(R3Equipment.PRIMAL_ARROWS.get(1).get(),3));
        check.accept(bow.getItem().use(l,p,InteractionHand.MAIN_HAND).getResult().consumesAction()&&p.isUsingItem(),"native bow nock uses original primal-ammunition hook");p.drawTicks(20);p.releaseUsingItem();var shot=shots(l).getFirst();check.accept(shots(l).size()==1&&shot.element()==0&&shot.isCritArrow(),"ordinary bow fires first inventory primal variant and marks full draw critical");check.accept(p.getInventory().getItem(2).getCount()==64&&p.getInventory().getItem(4).getCount()==2&&p.getInventory().getItem(5).getCount()==3&&bow.getDamageValue()==1,"one primal shot consumes only selected primal ammunition and one bow durability");check.accept(Math.abs(shot.getDeltaMovement().length()-3)<.12&&shot.pickup==AbstractArrow.Pickup.DISALLOWED,"ordinary bow uses original launch speed and forbids primal-arrow pickup");clearArrows(l);
        var bone=new ItemStack(R3Equipment.BONE_BOW.get());check.accept(bone.getMaxDamage()==512&&bone.getEnchantmentValue()==3&&bone.getItem() instanceof thaumcraft.api.IRepairable,"bone bow retains original durability, enchantability and Repair contract");p.setItemInHand(InteractionHand.MAIN_HAND,bone);bone.getItem().use(l,p,InteractionHand.MAIN_HAND);p.drawTicks(1);p.releaseUsingItem();check.accept(shots(l).isEmpty()&&bone.getDamageValue()==0,"undercharged bone bow produces no shot or durability loss");bone.getItem().use(l,p,InteractionHand.MAIN_HAND);p.drawTicks(18);bone.getItem().onUseTick(l,p,bone,72000-18);check.accept(p.isUsingItem()&&shots(l).isEmpty(),"eighteenth tick still holds the original automatic bow");p.drawTicks(19);bone.getItem().onUseTick(l,p,bone,72000-19);shot=shots(l).getFirst();check.accept(!p.isUsingItem()&&shots(l).size()==1&&!shot.isCritArrow()&&Math.abs(shot.getDeltaMovement().length()-3.75)<.14,"nineteenth tick automatically releases one noncritical fast primal shot");check.accept(p.getInventory().getItem(4).getCount()==1&&bone.getDamageValue()==1,"automatic release spends exactly one arrow and one durability");clearArrows(l);
        p.getInventory().setItem(4,ItemStack.EMPTY);p.getInventory().setItem(5,ItemStack.EMPTY);bone.getItem().use(l,p,InteractionHand.MAIN_HAND);p.drawTicks(10);p.releaseUsingItem();var ordinary=l.getEntitiesOfClass(Arrow.class,new AABB(POS).inflate(64)).getFirst();check.accept(Math.abs(ordinary.getDeltaMovement().length()-3.75)<.14&&!ordinary.isCritArrow()&&ordinary.getBaseDamage()==2.5&&p.getInventory().getItem(2).getCount()==63,"bone bow shoots ordinary arrows with original speed and half-point damage bonus");clearArrows(l);
        p.getInventory().setItem(2,ItemStack.EMPTY);var infinity=l.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(Enchantments.INFINITY);bone.enchant(infinity,1);check.accept(bone.getItem().use(l,p,InteractionHand.MAIN_HAND).getResult().consumesAction(),"original Infinity bone bow can nock with no ordinary arrow in inventory");p.drawTicks(10);p.releaseUsingItem();ordinary=l.getEntitiesOfClass(Arrow.class,new AABB(POS).inflate(64)).getFirst();check.accept(ordinary.pickup==AbstractArrow.Pickup.CREATIVE_ONLY,"Infinity's generated ordinary arrow cannot be collected in survival");clearArrows(l);
        p.getInventory().setItem(4,new ItemStack(R3Equipment.PRIMAL_ARROWS.get(2).get(),5));bone.getItem().use(l,p,InteractionHand.MAIN_HAND);p.drawTicks(10);p.releaseUsingItem();check.accept(p.getInventory().getItem(4).getCount()==4&&shots(l).getFirst().element()==2,"TC4 survival consumes a primal arrow even with Infinity");clearArrows(l);p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);var creativeBow=new ItemStack(Items.BOW);p.setItemInHand(InteractionHand.MAIN_HAND,creativeBow);creativeBow.getItem().use(l,p,InteractionHand.MAIN_HAND);p.drawTicks(20);p.releaseUsingItem();check.accept(p.getInventory().getItem(4).getCount()==3,"TC4 creative without Infinity still consumes a primal arrow");clearArrows(l);p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);
        p.setDeltaMovement(.7,.3,.9);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.BOW));p.getMainHandItem().getItem().use(l,p,InteractionHand.MAIN_HAND);p.drawTicks(20);p.releaseUsingItem();shot=shots(l).getFirst();check.accept(shot.getDeltaMovement().x<3.2&&Math.abs(shot.getDeltaMovement().y)<.2&&Math.abs(shot.getDeltaMovement().z)<.2,"original primal launch ignores moving shooter's horizontal and airborne velocity");clearArrows(l);p.setDeltaMovement(Vec3.ZERO);
        var enchBow=new ItemStack(R3Equipment.BONE_BOW.get());enchBow.enchant(l.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(Enchantments.POWER),2);enchBow.enchant(l.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(Enchantments.PUNCH),1);enchBow.enchant(l.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(Enchantments.FLAME),1);p.setItemInHand(InteractionHand.MAIN_HAND,enchBow);enchBow.getItem().use(l,p,InteractionHand.MAIN_HAND);p.drawTicks(10);p.releaseUsingItem();shot=shots(l).getFirst();var nativeDamage=shot.saveWithoutId(new CompoundTag()).getDouble("damage");check.accept(Math.abs(nativeDamage-(2.1+1+.5))<.0001&&shot.isOnFire(),"original inherited damage setter and Flame enchantment configure the first arrow pass");clearArrows(l);
        var moving=thaumcraft.entities.R3Entities.PRIMAL_ARROW.get().create(l);moving.setPos(POS.getCenter());moving.setDeltaMovement(1,.2,0);l.addFreshEntity(moving);l.tickNonPassenger(moving);check.accept(Math.abs(moving.getX()-(POS.getX()+.5)-1.99)<1e-6&&Math.abs(moving.getY()-(POS.getY()+.5)-.348)<1e-6,"original bytecode's two movement passes reproduce observed free-flight displacement");check.accept(Math.abs(moving.getDeltaMovement().x-.9801)<1e-6&&Math.abs(moving.getDeltaMovement().y-.09652)<1e-6&&moving.tickCount==1,"two original friction/gravity passes still advance one entity age tick");
        for(int i=0;i<6;i++){var arrow=new PrimalArrow(l,p,new ItemStack(R3Equipment.PRIMAL_ARROWS.get(i).get()),i);arrow.setDeltaMovement(3,0,0);var pig=target(l,i);check.accept(arrow.inflictDamage(pig),"elemental collision applies actual health damage: "+i);int expected=(int)Math.ceil(3*2.1*(i==3?1.5:i>=4?.8:1));check.accept(Math.abs(pig.getHealth()-(80-expected))<.001,"source-derived elemental damage multiplier is applied: "+i);if(i==1)check.accept(pig.getRemainingFireTicks()==100,"fire-arrow elemental hit ignites for exactly five seconds");if(i==2)check.accept(pig.getEffect(MobEffects.MOVEMENT_SLOWDOWN)!=null&&pig.getEffect(MobEffects.MOVEMENT_SLOWDOWN).getDuration()==200&&pig.getEffect(MobEffects.MOVEMENT_SLOWDOWN).getAmplifier()==4,"water arrow gives original ten-second Slowness V");if(i==4)check.accept(pig.getEffect(MobEffects.WEAKNESS)!=null&&pig.getEffect(MobEffects.WEAKNESS).getDuration()==200&&pig.getEffect(MobEffects.WEAKNESS).getAmplifier()==4,"order arrow gives original ten-second Weakness V");if(i==5)check.accept(pig.getEffect(MobEffects.WITHER)!=null&&pig.getEffect(MobEffects.WITHER).getDuration()==100&&pig.getEffect(MobEffects.WITHER).getAmplifier()==0,"entropy arrow gives original five-second Wither I");
            var tag=new CompoundTag();arrow.saveWithoutId(tag);var copy=thaumcraft.entities.R3Entities.PRIMAL_ARROW.get().create(l);copy.load(tag);check.accept(copy.element()==i&&copy.pickup==AbstractArrow.Pickup.DISALLOWED,"arrow type and prohibited pickup survive native NBT round trip: "+i);var values=arrow.getEntityData().getNonDefaultValues();if(values!=null)copy.getEntityData().assignValues(values);check.accept(copy.element()==i,"native entity-data synchronization retains primal type: "+i);arrow.discard();copy.discard();}
        var water=new PrimalArrow(l,p,new ItemStack(R3Equipment.PRIMAL_ARROWS.get(2).get()),2);water.igniteForSeconds(100);water.setDeltaMovement(3,0,0);var pig=target(l,7);water.inflictDamage(pig);check.accept(!pig.isOnFire(),"water elemental pass does not transfer arrow fire to its target");var fire=new PrimalArrow(l,p,new ItemStack(R3Equipment.PRIMAL_ARROWS.get(1).get()),1);fire.igniteForSeconds(100);fire.setDeltaMovement(3,0,0);pig=target(l,8);fire.inflictDamage(pig);check.accept(pig.getRemainingFireTicks()==200,"fire and Flame combine into original ten-second ignition");
        var armored=EntityType.ZOMBIE.create(l);armored.setItemSlot(EquipmentSlot.CHEST,new ItemStack(Items.IRON_CHESTPLATE));armored.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE,200,4));armored.setPos(POS.getX()+20,POS.getY()+10,POS.getZ()+30);var air=new PrimalArrow(l,p,new ItemStack(R3Equipment.PRIMAL_ARROWS.get(0).get()),0);air.setDeltaMovement(3,0,0);air.inflictDamage(armored);check.accept(armored.getHealth()<20&&armored.getHealth()>13,"actual source absolute-damage behavior ignores Resistance but keeps armor (shadowed unblockable flag)");
        var stopped=thaumcraft.entities.R3Entities.PRIMAL_ARROW.get().create(l);stopped.setPos(POS.getX()+.5,POS.getY()+4.5,POS.getZ()+.5);stopped.setDeltaMovement(1,0,0);l.setBlockAndUpdate(POS.offset(2,4,0),Blocks.STONE.defaultBlockState());l.addFreshEntity(stopped);for(int t=0;t<5&&!stopped.isRemoved()&&stopped.embeddedTicks()==0;t++)stopped.tick();check.accept(!stopped.isRemoved()&&stopped.embeddedTicks()>0,"original two-pass collision embeds primal arrow in a real solid block");for(int t=0;t<100&&stopped.embeddedTicks()<99&&!stopped.isRemoved();t++)stopped.tick();stopped.playerTouch(p);check.accept(!stopped.isRemoved()&&stopped.embeddedTicks()==99,"embedded arrow remains uncollectable before original hundred-tick fade completes");stopped.tick();check.accept(stopped.isRemoved(),"embedded primal arrow disappears after original one hundred ground ticks");l.setBlockAndUpdate(POS.offset(2,4,0),Blocks.AIR.defaultBlockState());
        clearArrows(l);for(int i=0;i<6;i++){var arrow=thaumcraft.entities.R3Entities.PRIMAL_ARROW.get().create(l);arrow.element(i);arrow.setPos(POS.getX()+3*i+.5,POS.getY()+12,POS.getZ()+16.5);arrow.setNoGravity(true);arrow.setDeltaMovement(Vec3.ZERO);arrow.setCritArrow(i%2==0);l.addFreshEntity(arrow);}check.accept(shots(l).size()==6,"all six native arrow entities are present before world persistence");var research=thaumcraft.data.ThaumcraftData.get(l.getServer()).research();check.accept(research.containsKey("BONEBOW")&&research.containsKey("PRIMALARROW")&&research.get("PRIMALARROW").recipePages().size()==6,"original bow and six-arrow recipe pages are included in research data");check.accept(research.get("PRIMALARROW").pageOrder().get(1).equals("PrimalArrows")&&research.get("PRIMALARROW").recipeVariants("PrimalArrows").size()==6,"six original recipes occupy one cycling book page in original text order");var sync=new CompoundTag();thaumcraft.data.ResearchDataSync.encode(sync,research);check.accept(thaumcraft.data.ResearchDataSync.decode(sync).get("PRIMALARROW").recipeVariants("PrimalArrows").equals(research.get("PRIMALARROW").recipeVariants("PrimalArrows")),"recipe-group order survives native server-to-client research synchronization");for(var a:R3Equipment.PRIMAL_ARROWS)check.accept(new ItemStack(a.get()).is(net.minecraft.tags.ItemTags.ARROWS),"native bow ammunition tag includes "+a.getId());
    }
    static void prepareReload(ServerLevel l){for(int x=-1;x<=3;x++)for(int z=-1;z<=3;z++){int cx=(POS.getX()>>4)+x,cz=(POS.getZ()>>4)+z;l.setChunkForced(cx,cz,true);l.getChunk(cx,cz);}}
    static boolean reloadReady(ServerLevel l){for(int x=-1;x<=3;x++)for(int z=-1;z<=3;z++)if(!l.areEntitiesLoaded(net.minecraft.world.level.ChunkPos.asLong((POS.getX()>>4)+x,(POS.getZ()>>4)+z)))return false;return true;}
    static void releaseChunks(ServerLevel l){for(int x=-1;x<=3;x++)for(int z=-1;z<=3;z++)l.setChunkForced((POS.getX()>>4)+x,(POS.getZ()>>4)+z,false);}
    static void reload(ServerLevel l,BiConsumer<Boolean,String> check){try{var all=shots(l);check.accept(all.size()==6,"six primal arrow entities survive an actual server restart");for(int i=0;i<6;i++){final int type=i;var arrow=all.stream().filter(a->a.element()==type).findFirst().orElseThrow();check.accept(arrow.pickup==AbstractArrow.Pickup.DISALLOWED&&arrow.isCritArrow()==(i%2==0)&&arrow.isNoGravity(),"persisted arrow variant, critical state, native gravity flag and pickup policy: "+i);}}finally{for(int i=0;i<6;i++){var p=POS.offset(i*3,12,16);l.setChunkForced(p.getX()>>4,p.getZ()>>4,false);}}}
}
